code.java:
public class DoublyLinkedListNode {
    int val;
    DoublyLinkedListNode next;
    DoublyLinkedListNode prev;
    DoublyLinkedListNode() {}
    DoublyLinkedListNode(int val) { this.val = val; }
}

public DoublyLinkedListNode reverse(DoublyLinkedListNode head) {
    DoublyLinkedListNode cur = head;
    DoublyLinkedListNode newHead = head;
    while (cur != null) {
        DoublyLinkedListNode nxt = cur.next;
        cur.next = cur.prev;
        cur.prev = nxt;
        newHead = cur;
        cur = nxt;
    }
    return newHead;
}

public DoublyLinkedListNode reverse(DoublyLinkedListNode head) {
    if (head == null) return null;
    DoublyLinkedListNode nxt = head.next;
    head.next = head.prev;
    head.prev = nxt;
    if (nxt == null) return head;
    return reverse(nxt);
}

