def reverse(self, head: DoublyLinkedListNode) -> DoublyLinkedListNode:
    if head is None:
        return None
    nxt = head.next
    head.next = head.prev
    head.prev = nxt
    if nxt is None:
        return head
    return self.reverse(nxt)

